MAP
   NAME cali
     Size 1000 600

     STATUS ON
     EXTENT  -76.5928 3.33181  -76.4613 3.50587
     SHAPEPATH "datos"

     FONTSET "misc/fonts/fonts.txt"
     SYMBOLSET "misc/symbols/symbols.sym"

      IMAGECOLOR 255 255 255
      UNITS dd

   WEB 
	IMAGEPATH "C:/ms4w/tmp/ms_tmp"  #puede variar

		IMAGEURL "/ms_tmp/"
	END
  
    LAYER
    #CONNECTIONTYPE postgis
      NAME "Cinco"
      STATUS ON
      DATA "cinco.shp"
      #CONNECTION "user=postgres password=123456 dbname=prueba host=localhost port=5433"
       # DATA "geom FROM (select * from cinco) as cinco using unique gid SRID=4326"
      TYPE POLYGON
        CLASS 
                    STYLE
                    
                          COLOR 200 200 200 # Nuevo color de relleno (gris claro)

                    END
          END
    END



    LAYER
      NAME "Six"
     DATA "six.shp"
      TYPE POLYGON
	    TRANSPARENCY 30 # Transparencia del 30%

     # LABELITEM "Comuna"
        CLASS
		#NAME "LABEL"
            STYLE
              COLOR 230 233 234
            END
		#	LABEL
		#	SIZE SMALL
		#	COLOR 0 0 0
		#	END
    END
   END

  LAYER
      NAME "One"
     DATA "one.shp"
      TYPE POLYGON
  TRANSPARENCY 70 # Transparencia del 70%

     LABELITEM "BARRIO"
        CLASS
		NAME "LABEL"
            STYLE
             COLOR 255 230 200 # Nuevo color de relleno (naranja claro)
    		OUTLINECOLOR 100 50 0 # Nuevo color de contorno (marrón oscuro)
            END
			LABEL
			SIZE SMALL
			COLOR 0 0 0
			END
        END
    END

LAYER 
		NAME "Two"

		STATUS ON
		DATA "two.shp"
  	    TYPE LINE
          TRANSPARENCY 40 # Transparencia del 50%

		#LABELITEM "BARRIO"
		CLASS 
			STYLE
				
				COLOR 120 120 120 # Gris medio (armoniza bien con el fondo)
				
			END


		END
	END


  CONFIG "MS_ERRORFILE" "C:/ms4w/apache/htdocs/log2.txt"
 	DEBUG 5
   



LAYER 
